function remaining(
  timer: ITimerBehaviorInstance<IInstance>,
  tag: string,
): number {
  return timer.isTimerRunning(tag)
    ? timer.getDuration(tag) - timer.getTotalTime(tag)
    : 0;
}

const cooldown = remaining(object.behaviors.Timer, "Cooldown");

callEventFunction(
  runtime,
  "PLR_EquipmentLoad",
  object.instVars.ItemName,
  cooldown,
  true,
);
